import {simulationPanelHTML,simulationPending} from './thesis-simulation-client.mjs';
import {supplementCheckPanel} from './supplement-check-panel.mjs';
import {thesisCompletionNeeds,safeCompletionIssues} from './thesis-completion-model.mjs';
import {thesisCoverFields,thesisManualBackMatter} from './thesis-delivery.mjs';
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function createCompletionDraft(){return {open:false,dirty:false,supplement:'',acknowledgements:'',metadata:{},materials:[],references:[],reference:{title:'',authors:'',year:'',doi:'',text:''},issues:[],messages:[],quote:null,requestKey:null,recheckRunId:null,simulationRunIds:[],simulationJob:null};}
export function completionPayload(draft,version){return {version,clientKey:draft.requestKey,supplement:draft.supplement,acknowledgements:draft.acknowledgements,metadata:draft.metadata,materials:draft.materials.map(({name,text})=>({name,text})),references:draft.references,...(draft.simulationRunIds?.length?{simulationRunIds:draft.simulationRunIds}:{})};}
export function completionDraftRecord(draft){const {quote,...record}=draft;return {...record,messages:[],issues:safeCompletionIssues(draft.issues)};}
export function restoreCompletionDraft(value){
 if(!value||typeof value!=='object'||typeof value.supplement!=='string'||value.supplement.length>50000||typeof value.acknowledgements!=='string'||value.acknowledgements.length>5000||!Array.isArray(value.materials)||value.materials.length>10||value.materials.some(row=>typeof row.name!=='string'||row.name.length>240||typeof row.text!=='string'||row.text.length>50000)||!Array.isArray(value.references)||value.references.length>30)throw Error('终稿补充草稿无效，请重新选择资料。');
 if(value.simulationRunIds!==undefined&&(!Array.isArray(value.simulationRunIds)||value.simulationRunIds.length>3||value.simulationRunIds.some(id=>typeof id!=='string'||id.length>100)))throw Error('模拟资料来源无效');
 if(value.simulationJob!==undefined&&value.simulationJob!==null){const job=value.simulationJob;if(typeof job!=='object'||typeof job.thesisId!=='string'||job.thesisId.length>100||typeof job.clientKey!=='string'||job.clientKey.length>100||!Number.isSafeInteger(job.version)||!['submitting','recovering','queued','running','completed','failed','cancelled'].includes(job.status)||job.jobId!==null&&typeof job.jobId!=='string'||String(job.text||'').length>40000)throw Error('模拟任务草稿无效');}
 const draft={...createCompletionDraft(),...value,quote:null,issues:safeCompletionIssues(value.issues)};if(!draft.metadata||Object.entries(draft.metadata).some(([key,text])=>!Object.hasOwn(thesisCoverFields,key)||typeof text!=='string'||text.length>200))throw Error('终稿封面草稿无效');for(const reference of [...draft.references,draft.reference])if(!reference||['title','authors','year','doi','text'].some(key=>typeof reference[key]!=='string'||reference[key].length>(key==='text'?50000:500)))throw Error('终稿文献草稿无效');return draft;
}
export function setCompletionIssues(draft,{report,formatting,additional=[]}={}){draft.open=true;draft.quote=null;draft.issues=safeCompletionIssues((report?.submission?.issues||[]).map(row=>row.code));const automatic=(report?.submission?.issues||[]).some(row=>/^(?:abstract_|keywords_|english_title|incomplete_manuscript|table_|raw_formula|duplicate_)/.test(row.code));draft.messages=[...new Set([...(report?.submission?.issues||[]).filter(row=>!/^(?:abstract_|keywords_|english_title|table_|raw_formula|duplicate_)/.test(row.code)).map(row=>row.code==='unresolved_placeholders'?'请按下方章节提示补充缺少的真实资料，系统会更新对应正文。':row.message),...(automatic?['系统将依据补齐后的正文整理摘要、关键词、英文题目及可自动处理的格式问题。']:[]),...(formatting?.unresolved||[]).map(row=>row.message),...additional].filter(value=>typeof value==='string'))].slice(0,40);}
export function completionProgressText(item,busy=false){return item.job?.stage==='checking_supplements'?'正在检查补充资料完整性，请稍候…':item.job?.status==='queued'?'资料已保存，正在排队检查与完善…':['running','cancelling'].includes(item.job?.status)?'正在自动完善正文与检查，完成后继续终稿编排…':busy?'正在保存资料并准备检查，请稍候…':'';}
export function completionPanelHTML(item,draft,{busy=false,costText=()=>''}={}){
 const wait=completionProgressText(item,busy);
 const checkUnavailable=item.quality?.supplementCheck?.status==='unavailable';
 const needs=thesisCompletionNeeds(item),ack=needs.chapters.some(row=>thesisManualBackMatter(row)),disabled=busy?'disabled':'',values={...item.snapshot?.requirements,...item.profile,...item.exportMetadata,...draft.metadata};
 return `<details class="thesis-completion-panel" data-thesis-completion data-optional-fields open><summary>补充材料，自动完善终稿</summary><div>${wait?`<section class="document-export-progress" data-completion-progress data-state="running" role="status" aria-live="polite"><div class="document-export-progress-heading"><span class="document-export-spinner" aria-hidden="true"></span><strong data-completion-progress-title>${esc(wait)}</strong></div><div class="document-export-track" role="progressbar" aria-label="资料检查与完善正在进行"><span></span></div><p>已保存的资料会继续使用，无需重复提交。完成后自动重新检查终稿。</p></section>`:''}${supplementCheckPanel(item.quality?.supplementCheck,{stale:item.quality?.stale||draft.dirty})}<p>系统先检查资料是否覆盖缺项；提供真实资料或明确标识的仿真资料后，系统完善相应章节、重新检查并排版。已有正文版本会保留。</p>${draft.messages.length?`<ul class="thesis-completion-requests" aria-label="本次终稿检查缺项">${draft.messages.map(message=>`<li>${esc(message)}</li>`).join('')}</ul>`:''}${needs.chapters.length?`<div class="thesis-completion-requests" tabindex="0" role="region" aria-label="需要补充的研究资料">${needs.chapters.map(chapter=>`<article><b>${esc(chapter.title)}</b><ul>${chapter.requests.map(text=>`<li>${esc(text)}</li>`).join('')}${chapter.needsTableTitles?'<li>表格名称与编号由系统在完善正文时整理。</li>':''}</ul></article>`).join('')}</div>`:''}<label>研究资料与实际结果<textarea data-completion-field="supplement" maxlength="50000" rows="5" placeholder="按缺项补充真实研究过程、实验或调查结果、数据说明。无需自己改写论文段落。" ${disabled}>${esc(draft.supplement)}</textarea></label><div data-thesis-simulation-host>${simulationPanelHTML(draft,{disabled:busy})}</div><div class="thesis-action-row"><label class="btn secondary">上传补充材料<input data-completion-file type="file" accept=".txt,.docx,.pdf" hidden ${disabled}></label><button type="button" class="btn secondary" data-completion-stored ${disabled}>从文件管理选择</button><select data-completion-purpose aria-label="附件用途" ${disabled}><option value="material">研究资料</option><option value="reference">文献原文</option></select></div><p data-completion-import-status role="status"></p>${draft.materials.length?`<ul>${draft.materials.map((row,index)=>`<li>${esc(row.name)} <button type="button" data-completion-remove-material="${index}" ${disabled}>移除</button></li>`).join('')}</ul>`:''}<details data-optional-fields open><summary>补充文献依据</summary><p>提供真实题录与可引用正文，系统根据内容建立引用。只有题录不能代替已阅读的文献。</p><div class="creation-row"><label>文献题名<input data-completion-reference="title" maxlength="500" value="${esc(draft.reference.title)}" ${disabled}></label><label>作者<input data-completion-reference="authors" maxlength="500" value="${esc(draft.reference.authors)}" ${disabled}></label></div><div class="creation-row"><label>年份<input data-completion-reference="year" maxlength="20" value="${esc(draft.reference.year)}" ${disabled}></label><label>DOI（可选）<input data-completion-reference="doi" maxlength="500" value="${esc(draft.reference.doi)}" ${disabled}></label></div><label>可引用的文献正文或已核对摘要<textarea data-completion-reference="text" maxlength="50000" rows="4" ${disabled}>${esc(draft.reference.text)}</textarea></label><button type="button" class="btn secondary" data-completion-add-reference ${disabled}>加入这篇文献</button>${draft.references.length?`<ul>${draft.references.map((row,index)=>`<li>${esc(row.title)} <button type="button" data-completion-remove-reference="${index}" ${disabled}>移除</button></li>`).join('')}</ul>`:''}</details>${ack?`<label>致谢事实<textarea data-completion-field="acknowledgements" maxlength="5000" rows="3" placeholder="填写希望感谢的人或机构及实际帮助，系统据此整理致谢，不虚构关系和资助。" ${disabled}>${esc(draft.acknowledgements)}</textarea></label>`:''}<details data-optional-fields open><summary>补充封面信息</summary><div class="thesis-cover-grid">${Object.entries(thesisCoverFields).map(([key,label])=>`<label>${label}<input data-completion-cover="${key}" maxlength="200" value="${esc(values[key]||'')}" ${disabled}></label>`).join('')}</div></details><div class="thesis-action-row"><button type="button" class="btn primary" data-completion-prepare ${disabled||simulationPending(draft)?'disabled':''}>${draft.dirty?'保存材料并自动完善':checkUnavailable?'重新检查并自动完善':'自动完善并检查终稿'}</button></div><p>保存资料和重新排版不扣写作积分。点击自动完善后，按可用套餐次数或积分处理，成功后结算。</p>${draft.quote?`<section class="thesis-completion-quote"><h4>本次自动完善</h4><p>涉及章节：${draft.quote.completion.chapterTitles.map(esc).join('、')}。</p><p>${esc(costText(draft.quote))}</p><p>完成后自动重新检查终稿；仍缺真实资料时继续提示，保留原有版本。</p><button type="button" class="btn primary" data-completion-start ${disabled}>确认费用，自动完善并检查终稿</button></section>`:''}<p data-completion-status role="status"></p></div></details>`;
}
export function updateCompletionPanelState(root,draft,{busy=false}={}){
 if(!root)return;
 const prepare=root.querySelector('[data-completion-prepare]');
 if(prepare){prepare.disabled=busy||simulationPending(draft);prepare.textContent=draft.dirty?'保存材料并自动完善':'自动完善并检查终稿';}
 if(!draft.quote)root.querySelector('.thesis-completion-quote')?.remove();
 if(draft.dirty){const state=root.querySelector('.supplement-check-panel header [role="status"]');if(state)state.textContent='内容或资料已更新，需要重新检查';}
}
export function bindCompletionPanel(root,draft,{changed,render,prepare,start,recheck,importFile,busy=()=>false}={}){
 if(!root)return;const change=()=>{draft.dirty=true;draft.quote=null;draft.requestKey=null;changed?.();const quote=root.querySelector('.thesis-completion-quote');quote?.remove();};
 root.addEventListener('toggle',()=>{draft.open=root.open;});
 root.querySelectorAll('[data-completion-field]').forEach(input=>input.addEventListener('input',()=>{draft[input.dataset.completionField]=input.value;change();}));
 root.querySelectorAll('[data-completion-cover]').forEach(input=>input.addEventListener('input',()=>{draft.metadata[input.dataset.completionCover]=input.value;change();}));
 root.querySelectorAll('[data-completion-reference]').forEach(input=>input.addEventListener('input',()=>{draft.reference[input.dataset.completionReference]=input.value;change();}));
 root.querySelector('[data-completion-add-reference]')?.addEventListener('click',()=>{if(busy())return;const reference=draft.reference,status=root.querySelector('[data-completion-status]');if(!reference.title.trim()||!reference.authors.trim()||!reference.year.trim()||!reference.text.trim()){status.textContent='请填写真实题名、作者、年份和可引用正文。';return;}if(draft.references.length>=30){status.textContent='本次最多补充 30 篇文献。';return;}draft.references.push({...reference});draft.reference={title:'',authors:'',year:'',doi:'',text:''};change();render();});
 for(const [selector,key]of [['[data-completion-remove-material]','materials'],['[data-completion-remove-reference]','references']])root.querySelectorAll(selector).forEach(button=>button.addEventListener('click',()=>{if(busy())return;draft[key].splice(Number(button.getAttribute(selector.slice(1,-1))),1);change();render();}));
 const input=root.querySelector('[data-completion-file]'),load=file=>{if(file&&!busy())void importFile(file,root.querySelector('[data-completion-purpose]').value,root.querySelector('[data-completion-import-status]'));};input?.addEventListener('change',()=>load(input.files?.[0]));
 root.querySelector('[data-completion-stored]')?.addEventListener('click',async()=>{if(!busy()){const {openStoredFilePicker}=await import('./file-picker.mjs');if(root.isConnected)openStoredFilePicker({input,onSelect:load,isCurrent:()=>root.isConnected});}});
 root.querySelector('[data-completion-prepare]')?.addEventListener('click',()=>void prepare());root.querySelector('[data-completion-start]')?.addEventListener('click',()=>void start());root.querySelector('[data-completion-recheck]')?.addEventListener('click',()=>{if(!draft.dirty)recheck();else root.querySelector('[data-completion-status]').textContent='请先保存补充材料，再由系统完善并检查。';});
}
